"use client";

import {
  type ButtonHTMLAttributes,
  createContext,
  type HTMLAttributes,
  type KeyboardEvent,
  type MouseEvent,
  type ReactNode,
  type RefObject,
  use,
  useCallback,
  useEffect,
  useId,
  useRef,
  useState,
} from "react";
import type { Align, Side } from "../interaction/floating";
import { useDismiss, useFloating, usePresence } from "../interaction/use-floating";
import { cx } from "../utils/cx";
import { flag } from "../utils/cx";
import { Slot } from "../utils/slot";

type MenuContextValue = {
  open: boolean;
  setOpen: (open: boolean) => void;
  triggerRef: RefObject<HTMLElement | null>;
  menuId: string;
  side: Side;
  align: Align;
};
const MenuContext = createContext<MenuContextValue | null>(null);

/** @internal Shared with ContextMenu, which anchors the same menu at the pointer instead of a trigger. */
export function useMenu(part: string): MenuContextValue {
  const ctx = use(MenuContext);
  if (!ctx) throw new Error(`<${part}> must be inside <DropdownMenu>`);
  return ctx;
}

export type DropdownMenuProps = {
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  side?: Side;
  align?: Align;
  children: ReactNode;
};

/**
 * The menu button pattern: a trigger that opens a list of actions. Arrow keys move through items (wrapping), Home and
 * End jump, typing a letter jumps to the next matching item, Escape closes and returns focus, Tab closes.
 */
export function DropdownMenu({
  open: controlled,
  defaultOpen = false,
  onOpenChange,
  side = "bottom",
  align = "start",
  children,
}: DropdownMenuProps) {
  const [uncontrolled, setUncontrolled] = useState(defaultOpen);
  const open = controlled ?? uncontrolled;
  const setOpen = useCallback(
    (next: boolean) => {
      if (controlled === undefined) setUncontrolled(next);
      onOpenChange?.(next);
    },
    [controlled, onOpenChange],
  );
  const triggerRef = useRef<HTMLElement>(null);
  const menuId = useId();
  return <MenuContext value={{ open, setOpen, triggerRef, menuId, side, align }}>{children}</MenuContext>;
}

export function DropdownMenuTrigger({
  asChild,
  onClick,
  onKeyDown,
  ...rest
}: ButtonHTMLAttributes<HTMLButtonElement> & { asChild?: boolean }) {
  const { open, setOpen, triggerRef, menuId } = useMenu("DropdownMenuTrigger");
  const Comp = asChild ? Slot : "button";
  return (
    <Comp
      {...(asChild ? {} : { type: "button" as const })}
      {...(rest as object)}
      ref={triggerRef as RefObject<HTMLButtonElement>}
      aria-haspopup="menu"
      aria-expanded={open}
      aria-controls={open ? menuId : undefined}
      onClick={(e: MouseEvent<HTMLButtonElement>) => {
        onClick?.(e);
        if (!e.defaultPrevented) setOpen(!open);
      }}
      onKeyDown={(e: KeyboardEvent<HTMLButtonElement>) => {
        onKeyDown?.(e);
        if (!e.defaultPrevented && (e.key === "ArrowDown" || e.key === "ArrowUp")) {
          e.preventDefault();
          setOpen(true);
        }
      }}
    />
  );
}

const ITEMS = '[role="menuitem"]:not([aria-disabled="true"])';

export function DropdownMenuContent({ className, onKeyDown, children, ...rest }: HTMLAttributes<HTMLDivElement>) {
  const { open, setOpen, triggerRef, menuId, side, align } = useMenu("DropdownMenuContent");
  const ref = useRef<HTMLDivElement>(null);
  const typed = useRef({ text: "", at: 0 });
  const { present, state } = usePresence(open);
  useFloating(present, triggerRef, ref, { side, align, offset: 6 });
  const close = useCallback(() => setOpen(false), [setOpen]);
  const refocus = useCallback(() => triggerRef.current?.focus(), [triggerRef]);
  useDismiss(open, triggerRef, ref, close, refocus);
  useEffect(() => {
    if (open) ref.current?.querySelector<HTMLElement>(ITEMS)?.focus({ preventScroll: true });
  }, [open]);
  if (!present) return null;

  const onKey = (e: KeyboardEvent<HTMLDivElement>) => {
    onKeyDown?.(e);
    if (e.defaultPrevented) return;
    const items = Array.from(e.currentTarget.querySelectorAll<HTMLElement>(ITEMS));
    const i = items.indexOf(document.activeElement as HTMLElement);
    let to = -1;
    if (e.key === "ArrowDown") to = (i + 1) % items.length;
    else if (e.key === "ArrowUp") to = (i - 1 + items.length) % items.length;
    else if (e.key === "Home") to = 0;
    else if (e.key === "End") to = items.length - 1;
    else if (e.key === "Tab") {
      close();
      return;
    } else if (e.key.length === 1 && !e.ctrlKey && !e.metaKey && !e.altKey && e.key !== " ") {
      const now = e.timeStamp;
      const t = typed.current;
      t.text = now - t.at > 700 ? e.key.toLowerCase() : t.text + e.key.toLowerCase();
      t.at = now;
      // repeated single letter cycles; a longer string matches a prefix starting from the current item
      const start = t.text.length === 1 ? i + 1 : Math.max(i, 0);
      for (let k = 0; k < items.length; k++) {
        const idx = (start + k) % items.length;
        if (items[idx]?.textContent?.trim().toLowerCase().startsWith(t.text)) {
          to = idx;
          break;
        }
      }
    }
    const target = items[to];
    if (to < 0 || !target) return;
    e.preventDefault();
    target.focus();
  };

  return (
    <div
      {...rest}
      ref={ref}
      data-state={state}
      inert={state === "closed" || undefined}
      id={menuId}
      popover="manual"
      role="menu"
      aria-orientation="vertical"
      className={cx("hm-floating hm-menu", className)}
      onKeyDown={onKey}
    >
      {children}
    </div>
  );
}

export type DropdownMenuItemProps = Omit<ButtonHTMLAttributes<HTMLButtonElement>, "onSelect"> & {
  asChild?: boolean;
  /** Runs when the item is chosen by click, Enter or Space. Call `event.preventDefault()` to keep the menu open. */
  onSelect?: (event: MouseEvent<HTMLElement>) => void;
  tone?: "default" | "danger";
};

export function DropdownMenuItem({
  asChild,
  onSelect,
  tone = "default",
  disabled,
  className,
  onClick,
  ...rest
}: DropdownMenuItemProps) {
  const { setOpen, triggerRef } = useMenu("DropdownMenuItem");
  const Comp = asChild ? Slot : "button";
  return (
    <Comp
      {...(asChild ? {} : { type: "button" as const })}
      {...(rest as object)}
      role="menuitem"
      tabIndex={-1}
      aria-disabled={disabled || undefined}
      data-tone={tone}
      data-disabled={flag(disabled)}
      className={cx("hm-menu-item", className)}
      onClick={(e: MouseEvent<HTMLButtonElement>) => {
        if (disabled) {
          e.preventDefault();
          return;
        }
        onClick?.(e);
        onSelect?.(e);
        if (!e.defaultPrevented) {
          setOpen(false);
          triggerRef.current?.focus();
        }
      }}
    />
  );
}

export function DropdownMenuLabel({ className, ...rest }: HTMLAttributes<HTMLDivElement>) {
  return <div {...rest} role="presentation" className={cx("hm-menu-label", className)} />;
}

export function DropdownMenuSeparator({ className, ...rest }: HTMLAttributes<HTMLDivElement>) {
  return <div {...rest} role="separator" className={cx("hm-menu-separator", className)} />;
}
